/**
 * Provider directory (#588): the long tail of OpenAI-compatible vendors, offered as
 * pre-filled Custom providers.
 *
 * `catalog.json` is a bundled snapshot of models.dev's provider list, regenerated by
 * `bun run directory:refresh` (see `scripts/refresh-provider-directory.ts`). It holds the
 * directory only: name, API root, docs link, logo. Every model fact still comes from the
 * provider's own `/models` (#586).
 */

import catalog from "./catalog.json";

export interface DirectoryEntry {
	/** models.dev's provider id, stored on the instance as `directoryId`. */
	id: string;
	name: string;
	/** The API root, used as the Custom provider's base URL as is. */
	api: string;
	/** Where the vendor documents its API (keys, pricing). */
	doc?: string;
	/** Sanitized monochrome SVG markup; see `DirectoryLogo.svelte`. */
	logo?: string;
}

const ENTRIES: readonly DirectoryEntry[] = catalog.entries;
const BY_ID = new Map(ENTRIES.map((entry) => [entry.id, entry]));

export function getDirectoryEntries(): readonly DirectoryEntry[] {
	return ENTRIES;
}

export function getDirectoryEntry(id: string | undefined): DirectoryEntry | undefined {
	return id ? BY_ID.get(id) : undefined;
}

/** The host shown under an entry's name, so look-alike resellers can be told apart. */
export function directoryHost(entry: DirectoryEntry): string {
	try {
		return new URL(entry.api).host;
	} catch {
		return entry.api;
	}
}

/** Case- and accent-insensitive match on the name, id and host. Empty query matches all. */
export function searchDirectory(query: string, entries: readonly DirectoryEntry[] = ENTRIES): DirectoryEntry[] {
	const fold = (s: string) => s.normalize("NFKD").replace(/\p{M}/gu, "").toLowerCase();
	const terms = fold(query).split(/\s+/).filter(Boolean);
	if (terms.length === 0) return [...entries];
	return entries.filter((entry) => {
		const haystack = fold(`${entry.name} ${entry.id} ${directoryHost(entry)}`);
		return terms.every((term) => haystack.includes(term));
	});
}
